<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { storeToRefs } from 'pinia'
import { Bell, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Circle, List, LoaderCircle, Plus, Trash2, X } from 'lucide-vue-next'
import { EVENT_COLORS, useCalendarStore } from '../stores/calendar'
import { useTodosStore } from '../stores/todos'
import { addDays, formatDate, holidayForDate, isInDateRange, monthCells, parseLocalDate, startOfWeek, todoCalendarItems, weekDays, yearMonths } from '../utils/calendar'
import { ensureReminderPermission, normalizedReminder, toDateTimeLocal } from '../services/reminders'
import ReminderEditor from '../components/ReminderEditor.vue'

const router = useRouter()
const calendar = useCalendarStore()
const todosStore = useTodosStore()
const { events, loading, error } = storeToRefs(calendar)
const anchor = ref(new Date())
const view = ref(localStorage.getItem('tiny-note-calendar-view') || 'month')
const viewMenu = ref(false)
const modal = ref(false)
const saving = ref(false)
const formError = ref('')
const selection = reactive({ active: false, start: '', end: '' })
const context = reactive({ visible: false, x: 0, y: 0, item: null })
const form = reactive({ title: '', startDate: '', endDate: '', startTime: '09:00', endTime: '10:00', allDay: false, description: '', color: '#1E88E5', priority: 'important', completed: false, reminder: { enabled: false, mode: 'at', triggerAt: '', offsetMinutes: 10, intervalMinutes: 10 } })
const weekdayLabels = ['一', '二', '三', '四', '五', '六', '日']
const views = [{ key: 'month', label: '月' }, { key: 'week', label: '周' }, { key: 'year', label: '年' }, { key: 'list', label: '列表' }]
const projectedTodos = computed(() => todoCalendarItems(todosStore.todos))
const allItems = computed(() => [...events.value.map(item => ({ ...item, kind: 'event' })), ...projectedTodos.value])
const cells = computed(() => monthCells(anchor.value.getFullYear(), anchor.value.getMonth(), allItems.value))
const days = computed(() => weekDays(anchor.value).map(day => ({ ...day, items: allItems.value.filter(item => item.startDate <= day.date && item.endDate >= day.date) })))
const months = computed(() => yearMonths(anchor.value.getFullYear(), allItems.value))
const listItems = computed(() => [...allItems.value].sort((a, b) => `${a.startDate}${a.startTime || ''}`.localeCompare(`${b.startDate}${b.startTime || ''}`)))
const label = computed(() => view.value === 'year' ? `${anchor.value.getFullYear()}年` : view.value === 'week' ? `${formatDate(startOfWeek(anchor.value))} — ${formatDate(addDays(startOfWeek(anchor.value), 6))}` : `${anchor.value.getFullYear()}年 ${anchor.value.getMonth() + 1}月`)

function setView(next) { view.value = next; viewMenu.value = false; localStorage.setItem('tiny-note-calendar-view', next) }
function move(direction) { const date = new Date(anchor.value); if (view.value === 'year') date.setFullYear(date.getFullYear() + direction); else if (view.value === 'week') date.setDate(date.getDate() + direction * 7); else date.setMonth(date.getMonth() + direction); anchor.value = date }
function today() { anchor.value = new Date() }
function resetForm(start = formatDate(new Date()), end = start) { Object.assign(form, { title: '', startDate: start, endDate: end, startTime: '09:00', endTime: '10:00', allDay: false, description: '', color: '#1E88E5', priority: 'important', completed: false, reminder: { enabled: false, mode: 'at', triggerAt: '', offsetMinutes: 10, intervalMinutes: 10 } }); formError.value = ''; modal.value = true }
function startSelect(date) { selection.active = true; selection.start = date; selection.end = date }
function extendSelect(date) { if (selection.active) selection.end = date }
function finishSelect() { if (!selection.active) return; const start = selection.start < selection.end ? selection.start : selection.end; const end = selection.start < selection.end ? selection.end : selection.start; selection.active = false; resetForm(start, end) }
async function saveEvent() {
  if (!form.title.trim()) { formError.value = '请输入日程标题'; return }
  try {
    saving.value = true; formError.value = ''
    const reminder = normalizedReminder(form.reminder, { hasAnchor: !form.allDay && Boolean(form.startTime) })
    if (reminder && !(await ensureReminderPermission())) { formError.value = '未获得系统通知权限，无法启用提醒'; return }
    await calendar.create({ title: form.title, startDate: form.startDate, endDate: form.endDate, startTime: form.allDay ? '' : form.startTime, endTime: form.allDay ? '' : form.endTime, allDay: form.allDay, description: form.description, color: form.color, priority: form.priority, completed: form.completed, reminder })
    modal.value = false
  } catch (reason) { formError.value = reason?.message || String(reason) } finally { saving.value = false }
}
function openItem(item) { if (item.kind === 'todo') router.push({ path: '/todos', query: { id: item.id } }); else router.push(`/calendar/${item.id}`) }
function openContext(event, item) { context.visible = true; context.x = event.clientX; context.y = event.clientY; context.item = item }
async function toggleContext() { const item = context.item; context.visible = false; if (!item) return; if (item.kind === 'todo') await todosStore.setCompleted(item.id, !item.completed); else await calendar.update(item.id, { ...item, completed: !item.completed, reminder: item.reminder?.enabled ? { ...item.reminder, triggerAt: item.reminder.triggerAt, offsetMinutes: item.reminder.offsetMinutes, intervalMinutes: item.reminder.intervalMinutes } : null }) }
async function deleteContext() { const item = context.item; context.visible = false; if (item?.kind === 'event' && window.confirm('确定删除这个日程吗？')) await calendar.remove(item.id) }
function eventStyle(item) { return { backgroundColor: `${item.color}${item.completed ? '18' : '32'}`, borderLeftColor: item.color } }
function monthClick(month) { anchor.value = new Date(anchor.value.getFullYear(), month, 1); setView('month') }
function closeMenus(event) { if (!event.target.closest?.('.calendar-view-switch')) viewMenu.value = false; if (!event.target.closest?.('.calendar-context')) context.visible = false }
function onKey(event) { if (event.key === 'Escape') { modal.value = false; context.visible = false; viewMenu.value = false } }
onMounted(async () => { document.addEventListener('pointerdown', closeMenus); window.addEventListener('keydown', onKey); await Promise.allSettled([calendar.load(), todosStore.load()]) })
onUnmounted(() => { document.removeEventListener('pointerdown', closeMenus); window.removeEventListener('keydown', onKey) })
</script>

<template>
  <section class="calendar-page">
    <header class="calendar-toolbar">
      <div class="calendar-nav"><button @click="move(-1)"><ChevronLeft :size="18" /></button><button class="today" @click="today">今天</button><button @click="move(1)"><ChevronRight :size="18" /></button><h1>{{ label }}</h1></div>
      <div class="calendar-actions"><div class="calendar-view-switch"><button @click.stop="viewMenu = !viewMenu">{{ views.find(item => item.key === view)?.label }}<ChevronDown :size="14" /></button><div v-if="viewMenu" class="calendar-view-menu"><button v-for="item in views" :key="item.key" :class="{ active: view === item.key }" @click="setView(item.key)"><Check v-if="view === item.key" :size="14" /><span v-else></span>{{ item.label }}</button></div></div><button class="primary" @click="resetForm()"><Plus :size="16" />新建日程</button></div>
    </header>
    <div v-if="loading" class="calendar-state"><LoaderCircle class="spin" :size="20" />正在读取日程…</div>
    <div v-else-if="error" class="calendar-state error">{{ error }}<button @click="calendar.load()">重试</button></div>
    <template v-else>
      <div v-if="view === 'month'" class="calendar-month"><div v-for="day in weekdayLabels" :key="day" class="weekday">周{{ day }}</div><div v-for="cell in cells" :key="cell.date" class="month-cell" :class="{ muted: !cell.isCurrentMonth, today: cell.isToday, selected: isInDateRange(cell.date, selection.start, selection.end) }" @mousedown.prevent="startSelect(cell.date)" @mouseenter="extendSelect(cell.date)" @mouseup.prevent="finishSelect"><div class="cell-head"><b>{{ cell.day === 1 ? `${parseLocalDate(cell.date).getMonth() + 1}月1日` : cell.day }}</b><small v-if="holidayForDate(cell.date)">{{ holidayForDate(cell.date).holiday }}</small></div><div class="cell-items"><button v-for="item in cell.events.slice(0, 4)" :key="`${item.kind}-${item.id}`" class="calendar-chip" :class="{ todo: item.kind === 'todo', completed: item.completed }" :style="eventStyle(item)" @mousedown.stop @click.stop="openItem(item)" @contextmenu.prevent.stop="openContext($event, item)"><Circle v-if="item.kind === 'todo'" :size="9" fill="currentColor" /><span>{{ item.title }}</span><Bell v-if="item.reminder?.enabled" :size="10" /></button><small v-if="cell.events.length > 4" class="more">+{{ cell.events.length - 4 }} 项</small></div></div></div>
      <div v-else-if="view === 'week'" class="calendar-week"><article v-for="day in days" :key="day.date" :class="{ today: day.isToday }" @dblclick="resetForm(day.date)"><header><span>{{ day.weekday }}</span><b>{{ day.day }}</b></header><div class="week-items"><button v-for="item in day.items" :key="`${item.kind}-${item.id}`" :style="eventStyle(item)" :class="{ completed: item.completed }" @click="openItem(item)" @contextmenu.prevent="openContext($event, item)"><strong>{{ item.title }}</strong><small>{{ item.allDay ? '全天' : item.startTime || '待办' }}</small></button><span v-if="!day.items.length" class="week-empty">双击新建</span></div></article></div>
      <div v-else-if="view === 'year'" class="calendar-year"><button v-for="month in months" :key="month.month" @click="monthClick(month.month)"><strong>{{ month.month + 1 }}月</strong><span class="mini-week"><i v-for="day in weekdayLabels" :key="day">{{ day }}</i></span><span class="mini-grid"><i v-for="cell in month.cells" :key="cell.date" :class="{ today: cell.isToday, busy: cell.events.length }">{{ cell.day }}</i></span></button></div>
      <div v-else class="calendar-list"><header><div><b>{{ listItems.length }}</b><span>全部事项</span></div><div><b>{{ listItems.filter(item => item.completed).length }}</b><span>已完成</span></div><div><b>{{ listItems.filter(item => item.kind === 'todo').length }}</b><span>待办投影</span></div></header><button v-for="item in listItems" :key="`${item.kind}-${item.id}`" @click="openItem(item)" @contextmenu.prevent="openContext($event, item)"><span class="list-dot" :style="{ background: item.color }"></span><span><strong :class="{ completed: item.completed }">{{ item.title }}</strong><small>{{ item.startDate }} {{ item.allDay ? '全天' : item.startTime }}</small></span><em>{{ item.kind === 'todo' ? '待办' : item.priority === 'urgent' ? '紧急' : item.priority === 'minor' ? '次要' : '重要' }}</em></button><div v-if="!listItems.length" class="calendar-empty"><CalendarDays :size="34" /><b>暂无日程和待办</b><span>新建日程，或为待办设置截止时间。</span></div></div>
    </template>

    <div v-if="modal" class="calendar-modal-backdrop" @mousedown.self="modal = false"><form class="calendar-modal" @submit.prevent="saveEvent"><header><h2>新建日程</h2><button type="button" @click="modal = false"><X :size="18" /></button></header><label>标题<input v-model="form.title" autofocus placeholder="日程标题"></label><div class="form-grid"><label>开始日期<input v-model="form.startDate" type="date"></label><label>结束日期<input v-model="form.endDate" type="date"></label></div><label class="check"><input v-model="form.allDay" type="checkbox">全天</label><div v-if="!form.allDay" class="form-grid"><label>开始时间<input v-model="form.startTime" type="time"></label><label>结束时间<input v-model="form.endTime" type="time"></label></div><label>描述<textarea v-model="form.description" rows="3" placeholder="添加描述…"></textarea></label><div class="form-grid"><label>优先级<select v-model="form.priority"><option value="urgent">紧急</option><option value="important">重要</option><option value="minor">次要</option></select></label><fieldset><legend>颜色</legend><div class="color-grid"><button v-for="color in EVENT_COLORS" :key="color" type="button" :class="{ active: form.color === color }" :style="{ background: color }" @click="form.color = color"></button></div></fieldset></div><ReminderEditor v-model="form.reminder" :has-anchor="!form.allDay && Boolean(form.startTime)" /><p v-if="formError" class="form-error">{{ formError }}</p><footer><button type="button" @click="modal = false">取消</button><button class="primary" :disabled="saving">{{ saving ? '保存中…' : '保存' }}</button></footer></form></div>
    <div v-if="context.visible" class="calendar-context" :style="{ left: `${context.x}px`, top: `${context.y}px` }"><button @click="toggleContext">{{ context.item?.completed ? '取消完成' : '标记完成' }}</button><button @click="openItem(context.item); context.visible = false">查看详情</button><button v-if="context.item?.kind === 'event'" class="danger" @click="deleteContext"><Trash2 :size="14" />删除日程</button></div>
  </section>
</template>

<style scoped>
.calendar-page{height:100%;display:flex;flex-direction:column;background:var(--bg);color:var(--text);overflow:hidden}.calendar-toolbar{height:62px;display:flex;align-items:center;justify-content:space-between;padding:0 22px;border-bottom:1px solid var(--line);flex:none}.calendar-nav,.calendar-actions,.calendar-view-switch>button,.calendar-toolbar button{display:flex;align-items:center;gap:6px}.calendar-toolbar button{border:1px solid var(--line);background:var(--panel);color:var(--text);border-radius:7px;padding:7px 10px;cursor:pointer}.calendar-nav h1{font-size:18px;margin:0 0 0 8px}.calendar-nav .today{font-weight:600}.calendar-actions{gap:10px}.calendar-actions .primary,.calendar-modal .primary{background:var(--accent);border-color:var(--accent);color:#fff}.calendar-view-switch{position:relative}.calendar-view-menu{position:absolute;right:0;top:40px;z-index:20;width:110px;background:var(--panel);border:1px solid var(--line);box-shadow:0 10px 30px #0002;border-radius:9px;padding:5px}.calendar-view-menu button{width:100%;border:0}.calendar-view-menu button span,.calendar-view-menu svg{width:14px}.calendar-view-menu .active{color:var(--accent)}.calendar-state,.calendar-empty{display:flex;align-items:center;justify-content:center;gap:10px;height:100%;color:var(--muted)}.calendar-state.error{color:#dc2626}.calendar-month{flex:1;min-height:0;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));grid-template-rows:32px repeat(6,minmax(76px,1fr))}.weekday{text-align:center;padding:8px;border-bottom:1px solid var(--line);color:var(--muted);font-size:12px}.month-cell{min-width:0;border-right:1px solid var(--line);border-bottom:1px solid var(--line);padding:5px;background:var(--panel);overflow:hidden}.month-cell.muted{background:color-mix(in srgb,var(--panel),var(--bg) 45%);color:var(--muted)}.month-cell.today .cell-head b{background:var(--accent);color:white;border-radius:50%;min-width:24px;height:24px;display:grid;place-items:center}.month-cell.selected{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--accent),transparent 55%)}.cell-head{display:flex;align-items:center;justify-content:space-between;height:25px;font-size:12px}.cell-head small{color:#dc2626;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cell-items{display:grid;gap:3px}.calendar-chip{width:100%;min-width:0;height:20px;border:0;border-left:3px solid;border-radius:4px;display:flex;align-items:center;gap:4px;padding:0 5px;color:var(--text);font-size:11px;text-align:left;cursor:pointer}.calendar-chip span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.calendar-chip.todo{border-left-style:dashed}.completed{text-decoration:line-through;opacity:.58}.more{color:var(--muted);padding-left:5px}.calendar-week{flex:1;min-height:0;display:grid;grid-template-columns:repeat(7,minmax(120px,1fr));overflow:auto}.calendar-week article{border-right:1px solid var(--line);background:var(--panel);min-height:100%}.calendar-week article>header{height:70px;display:grid;place-items:center;border-bottom:1px solid var(--line);color:var(--muted)}.calendar-week article>header b{font-size:22px;color:var(--text)}.calendar-week article.today>header b{background:var(--accent);color:#fff;border-radius:50%;width:34px;height:34px;display:grid;place-items:center}.week-items{padding:8px;display:grid;align-content:start;gap:8px}.week-items button{border:0;border-left:3px solid var(--accent);border-radius:7px;padding:9px;text-align:left;color:var(--text);display:grid;gap:4px}.week-items small,.week-empty{color:var(--muted)}.calendar-year{flex:1;overflow:auto;padding:18px;display:grid;grid-template-columns:repeat(4,minmax(190px,1fr));gap:14px}.calendar-year>button{border:1px solid var(--line);background:var(--panel);border-radius:10px;padding:13px;color:var(--text);text-align:left;cursor:pointer}.mini-week,.mini-grid{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;margin-top:10px}.mini-week i{font-style:normal;color:var(--muted);font-size:10px}.mini-grid i{font-style:normal;font-size:11px;padding:4px 0;border-radius:50%}.mini-grid i.busy{color:var(--accent);font-weight:700}.mini-grid i.today{background:var(--accent);color:#fff}.calendar-list{flex:1;overflow:auto;padding:20px;max-width:1000px;width:100%;box-sizing:border-box;margin:auto}.calendar-list>header{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.calendar-list>header div{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:14px;display:grid;gap:4px}.calendar-list>header b{font-size:22px}.calendar-list>header span{color:var(--muted)}.calendar-list>button{width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--text);padding:13px 9px;display:grid;grid-template-columns:10px 1fr auto;gap:12px;text-align:left}.calendar-list>button span:nth-child(2){display:grid;gap:4px}.calendar-list small{color:var(--muted)}.calendar-list em{font-style:normal;color:var(--muted);font-size:12px}.list-dot{width:8px;height:8px;border-radius:50%;margin-top:5px}.calendar-empty{height:300px;flex-direction:column}.calendar-modal-backdrop{position:fixed;inset:0;z-index:80;background:#0006;display:grid;place-items:center}.calendar-modal{width:min(540px,calc(100vw - 32px));max-height:calc(100vh - 50px);overflow:auto;background:var(--panel);border:1px solid var(--line);border-radius:13px;box-shadow:0 24px 70px #0005;padding:18px;display:grid;gap:14px}.calendar-modal header,.calendar-modal footer{display:flex;align-items:center;justify-content:space-between}.calendar-modal h2{font-size:18px;margin:0}.calendar-modal label{display:grid;gap:6px;font-size:13px}.calendar-modal input,.calendar-modal textarea,.calendar-modal select{box-sizing:border-box;width:100%;border:1px solid var(--line);background:var(--bg);color:var(--text);border-radius:7px;padding:8px;font:inherit}.calendar-modal header button,.calendar-modal footer button{border:1px solid var(--line);background:var(--bg);color:var(--text);border-radius:7px;padding:8px 13px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.calendar-modal .check{display:flex;align-items:center}.calendar-modal .check input{width:auto}.calendar-modal fieldset{border:0;padding:0;margin:0}.calendar-modal legend{font-size:13px;margin-bottom:8px}.color-grid{display:flex;flex-wrap:wrap;gap:6px}.color-grid button{width:22px;height:22px;border:2px solid transparent;border-radius:50%}.color-grid button.active{box-shadow:0 0 0 2px var(--panel),0 0 0 4px var(--accent)}.form-error{margin:0;color:#dc2626;font-size:12px}.calendar-context{position:fixed;z-index:100;min-width:150px;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:5px;box-shadow:0 12px 35px #0004;display:grid}.calendar-context button{border:0;background:transparent;color:var(--text);padding:8px 10px;text-align:left;border-radius:5px;display:flex;gap:7px}.calendar-context button:hover{background:var(--hover)}.calendar-context .danger{color:#dc2626}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:900px){.calendar-year{grid-template-columns:repeat(2,minmax(190px,1fr))}.calendar-week{grid-template-columns:repeat(7,150px)}.calendar-toolbar{padding:0 10px}.calendar-nav h1{font-size:14px}.calendar-actions .primary{font-size:0}.calendar-actions .primary svg{margin:0}.month-cell{padding:3px}.cell-head small{display:none}}
</style>
